/bin/zsh -lc "./run_python - <<'PY'
import json, sys
print('recursion limit:', sys.getrecursionlimit())
for kind in ('list', 'dict'):
    for depth in (100, 500, 1000, 2000, 4000, 8000):
        value = None
        for _ in range(depth):
            value = [value] if kind == 'list' else {'x': value}
        try:
            encoded = json.dumps(value, allow_nan=False)
        except RecursionError:
            print(kind, depth, 'encoder rejected')
            break
        try:
            json.loads(encoded)
        except RecursionError:
            print(kind, depth, 'DECODER REJECTED')
            break
        print(kind, depth, 'round trip succeeded')
PY"
